old_string:
let slot = 0;
const toHdr = (net, src, jPad) => {
  if (!net || !src || !jPad) return;
  const s = slot++;
  const riseX = 2620 + s * 45;
  const runY = 70 + s * 35;
  const esc = { x: src.x + (src.x < 2000 ? 40 : -40), y: src.y };
  add(net, src, esc, 12, 'F.Cu');
  addVia(net, esc);
  // 长跑全 B：竖→横→竖，互异 runY / riseX，不占 F
  L(net, [
    esc, { x: esc.x, y: runY }, { x: riseX, y: runY }, { x: riseX, y: jPad.y }
  ], 12, 'B.Cu');
  addVia(net, { x: riseX, y: jPad.y });
  add(net, { x: riseX, y: jPad.y }, jPad, 12, 'F.Cu');
};

new_string:
let slot = 0;
const toHdr = (net, src, jPad) => {
  if (!net || !src || !jPad) return;
  const s = slot++;
  const riseX = 2650 + s * 45;
  const runY = 60 + s * 32;
  // 板内走 F（横/竖分层靠互异 runY）；仅右缘 riseX 用 B 下落，避开本地 B 绕行
  L(net, [
    src, { x: src.x, y: runY }, { x: riseX, y: runY }
  ], 12, 'F.Cu');
  addVia(net, { x: riseX, y: runY });
  add(net, { x: riseX, y: runY }, { x: riseX, y: jPad.y }, 12, 'B.Cu');
  addVia(net, { x: riseX, y: jPad.y });
  add(net, { x: riseX, y: jPad.y }, jPad, 12, 'F.Cu');
};
